CREATE TABLE public.app_owner (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), user_id uuid NOT NULL UNIQUE);
GRANT SELECT ON public.app_owner TO authenticated;
GRANT ALL ON public.app_owner TO service_role;
ALTER TABLE public.app_owner ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner reads own identity" ON public.app_owner FOR SELECT TO authenticated USING (user_id = auth.uid());
INSERT INTO public.app_owner(singleton,user_id) SELECT true, r.user_id FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.role='admin' ORDER BY u.created_at LIMIT 1;
CREATE OR REPLACE FUNCTION public.is_app_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.app_owner WHERE user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_app_owner() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_app_owner() TO authenticated;
CREATE OR REPLACE FUNCTION public.handle_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN new; END $$;
COMMENT ON FUNCTION public.handle_first_admin() IS 'Automatic admin assignment disabled: new accounts require owner approval.';
CREATE TABLE public.access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, email text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, decided_by uuid);
GRANT SELECT ON public.access_requests TO authenticated;
GRANT ALL ON public.access_requests TO service_role;
ALTER TABLE public.access_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own or owner requests" ON public.access_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_app_owner());
CREATE OR REPLACE FUNCTION public.request_app_access() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_email text; v_new boolean := false; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT email INTO v_email FROM auth.users WHERE id=auth.uid() AND (email_confirmed_at IS NOT NULL OR phone_confirmed_at IS NOT NULL); IF v_email IS NULL THEN RAISE EXCEPTION 'Confirma tu correo primero'; END IF; IF public.has_role(auth.uid(),'admin') THEN RETURN jsonb_build_object('status','approved','created',false); END IF; INSERT INTO public.access_requests(user_id,email) VALUES(auth.uid(),v_email) ON CONFLICT(user_id) DO NOTHING RETURNING id INTO v_id; v_new := v_id IS NOT NULL; RETURN (SELECT jsonb_build_object('id',id,'email',email,'status',status,'created',v_new) FROM public.access_requests WHERE user_id=auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.request_app_access() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_app_access() TO authenticated;
CREATE OR REPLACE FUNCTION public.decide_app_access(p_id uuid,p_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_user uuid; BEGIN IF NOT public.is_app_owner() THEN RAISE EXCEPTION 'Solo el dueño puede aprobar solicitudes'; END IF; SELECT user_id INTO v_user FROM public.access_requests WHERE id=p_id AND status='pending' FOR UPDATE; IF v_user IS NULL THEN RAISE EXCEPTION 'La solicitud no está pendiente'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=v_user) THEN RAISE EXCEPTION 'La cuenta ya no existe'; END IF; UPDATE public.access_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,decided_at=now(),decided_by=auth.uid() WHERE id=p_id; IF p_approve THEN INSERT INTO public.user_roles(user_id,role) VALUES(v_user,'admin') ON CONFLICT(user_id,role) DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.decide_app_access(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.decide_app_access(uuid,boolean) TO authenticated;